def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width colored rows encode a repeating horizontal band pattern.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        colors = {r % period: color for r, color in bars}
        return [[colors[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise, parallel down-right diagonals encode the repeating pattern.
    diagonals = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in diagonals and diagonals[d] != color:
                    raise ValueError('inconsistent color on diagonal')
                diagonals[d] = color
    period = len(diagonals)
    if not period:
        return [row[:] for row in grid]
    colors = {d % period: color for d, color in diagonals.items()}
    return [[colors[(c - r) % period] for c in range(w)] for r in range(h)]
